import{_ as o,o as a,c as d,a2 as t}from"./chunks/framework.BS0bAV7E.js";const p=JSON.parse('{"title":"贡献者移植性须知","description":"","frontmatter":{},"headers":[],"relativePath":"zh/dev/portability.md","filePath":"zh/dev/portability.md"}'),c={name:"zh/dev/portability.md"};function r(i,e,n,l,s,h){return a(),d("div",null,[...e[0]||(e[0]=[t('<h1 id="贡献者移植性须知" tabindex="-1">贡献者移植性须知 <a class="header-anchor" href="#贡献者移植性须知" aria-label="Permalink to &quot;贡献者移植性须知&quot;">​</a></h1><p>本地使用 GCC 14.x 构建，CI 上使用更新的工具链构建。 已有三类差异造成问题 - 请牢记：</p><h2 id="_1-新版-gcc-更严格的警告类别" tabindex="-1">1. 新版 GCC 更严格的警告类别 <a class="header-anchor" href="#_1-新版-gcc-更严格的警告类别" aria-label="Permalink to &quot;1. 新版 GCC 更严格的警告类别&quot;">​</a></h2><p><code>-Waddress-of-packed-member</code>（自 GCC 9 起包含在 <code>-Wall</code> 中，新版执行更严格）：在 <code>-Werror</code> 下，将打包结构体指针转换为自然对齐类型是错误。multiboot2 标签类型正是因此原因全部声明为 <code>__attribute__((packed))</code> - 包括 mmap 标签（4 个 u32，无布局变化）和 BASIC_MEMINFO 读取器，它通过打包的标签类型而非裸 <code>u32*</code> 转换来访问。</p><p>规则：当转换来自打包内存的指针时，目标类型应为打包类型。</p><h2 id="_2-更严格的汇编器-binutils-gas" tabindex="-1">2. 更严格的汇编器（binutils/GAS） <a class="header-anchor" href="#_2-更严格的汇编器-binutils-gas" aria-label="Permalink to &quot;2. 更严格的汇编器（binutils/GAS）&quot;">​</a></h2><p><code>setcc</code>/<code>setc</code> 仅接受字节寄存器。rdrand 包装器将其标志声明为 <code>u32</code>，约束为 <code>&quot;=q&quot;</code> - 较旧 GAS 会静默截断到字节子寄存器，新版 GAS 拒绝操作数大小。现在是 <code>u8</code>。</p><p>规则：setcc 样式的标志是 <code>u8</code>，约束为 <code>&quot;=q&quot;</code>。</p><h2 id="_3-工具链布局假设" tabindex="-1">3. 工具链布局假设 <a class="header-anchor" href="#_3-工具链布局假设" aria-label="Permalink to &quot;3. 工具链布局假设&quot;">​</a></h2><p><code>OC_TOOLS</code> 可能指向可重定位树（<code>&lt;root&gt;/usr/{bin,lib}</code>）或系统根（<code>/usr</code>，其下直接有 <code>{bin,lib}</code>）。embed_grub 生成器探测两种布局 - 不要假设其中任何一种。</p><h2 id="编译标志约定" tabindex="-1">编译标志约定 <a class="header-anchor" href="#编译标志约定" aria-label="Permalink to &quot;编译标志约定&quot;">​</a></h2><p>内核标志在 Makefile 中固定： <code>-ffreestanding -fno-stack-protector -fno-pie -fno-pic -mno-red-zone -mno-sse -mno-mmx -mno-3dnow -mcmodel=kernel -fno-asynchronous-unwind-tables -Wall -Wextra -Werror -O2 -g -std=gnu11</code>。新标志应放在 Makefile（一处）中，而不是分散在各文件中。</p><h2 id="交叉构建" tabindex="-1">交叉构建 <a class="header-anchor" href="#交叉构建" aria-label="Permalink to &quot;交叉构建&quot;">​</a></h2><p><code>make ARCH=arm64</code> / <code>ARCH=riscv</code> 使用 aarch64/riscv64 交叉工具链和它们自己的链接规则（<code>--hash-style=sysv --build-id=none</code>；<code>-n</code> 和 PHDR 布局不兼容）。点亮 Shell 是真实的（PL011/NS16550A 除法器、定时器计数器、心跳），但故意保持最小 - x86_64 是功能完整的架构。</p>',14)])])}const _=o(c,[["render",r]]);export{p as __pageData,_ as default};
